import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String raw = new String(System.in.readAllBytes(), "UTF-8");
        // The JSON holds only [new, old] pairs of lowercase strings: collect the quoted strings in order.
        List<String> strs = new ArrayList<>();
        for (int p = 0; p < raw.length(); p++) {
            if (raw.charAt(p) != '"') continue;
            int q = raw.indexOf('"', p + 1);
            strs.add(raw.substring(p + 1, q));
            p = q;
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i + 1 < strs.size(); i += 2) {
            String nw = strs.get(i), old = strs.get(i + 1);
            int j = 0;
            // Greedy: match old[j] at the earliest position equal to it or to its cyclic predecessor.
            for (int t = 0; t < nw.length(); t++) {
                char c = nw.charAt(t), next = c == 'z' ? 'a' : (char) (c + 1);
                if (j < old.length() && (c == old.charAt(j) || next == old.charAt(j))) j++;
            }
            out.append(j == old.length() ? "YES\n" : "NO\n");
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	// The JSON holds only [new, old] pairs of lowercase strings: collect the quoted strings in order.
	parts := strings.Split(string(raw), "\"")
	var strs []string
	for i := 1; i < len(parts); i += 2 {
		strs = append(strs, parts[i])
	}
	var out strings.Builder
	for i := 0; i+1 < len(strs); i += 2 {
		nw, old := strs[i], strs[i+1]
		j := 0
		// Greedy: match old[j] at the earliest position equal to it or to its cyclic predecessor.
		for t := 0; t < len(nw); t++ {
			c := nw[t]
			next := c + 1
			if c == 'z' {
				next = 'a'
			}
			if j < len(old) && (c == old[j] || next == old[j]) {
				j++
			}
		}
		if j == len(old) {
			out.WriteString("YES\n")
		} else {
			out.WriteString("NO\n")
		}
	}
	os.Stdout.WriteString(out.String())
}
